export default '/**\n * Stackra file contract:\n * Purpose: the "weekly" demo of the native RecurrenceEditor: a stand-up on Sunday, Tuesday and Thursday; change the\n *          days, the interval or the frequency and read the stored RRULE text under the editor.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decision 3); ADR 0060;\n *          STA-1371 (owner request 2026-10-29).\n */\nimport { CalendarDate } from "@internationalized/date";\nimport { RecurrenceEditor, Text, useCatalogueText } from "@stackra/ui/native";\nimport { useState } from "react";\nimport { View } from "react-native";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { RECURRENCE_EDITOR_DEMO_KEYS } from "#src/demos/free/recurrence-editor/recurrence-editor-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = RECURRENCE_EDITOR_DEMO_KEYS.demo_free.recurrence_editor;\n\n/** A weekly rule on three days, with the stored rule string shown below. */\nexport default function Weekly() {\n  const t = useCatalogueText(MESSAGES.en);\n  const [rule, setRule] = useState("FREQ=WEEKLY;BYDAY=SU,TU,TH");\n  return (\n    <View className="gap-4">\n      <RecurrenceEditor\n        label={t(K.weekly)}\n        startDate={new CalendarDate(2026, 11, 1)}\n        value={rule}\n        onChange={setRule}\n      />\n      <Text type="small" tone="muted">{`${t(K.stored)} ${rule}`}</Text>\n    </View>\n  );\n}\n';
